"""Encode manually read image-paper findings; use Crossref only for bibliographic joins."""
import json
from pathlib import Path
import sys
sys.stdout.reconfigure(encoding='utf-8')
ROOT=Path(__file__).resolve().parents[1]
RAW=ROOT/'evidence/raw/image'
B={'papers':[],'sources':[],'claims':[],'claim_evidence':[],'searches':[],'excluded':[],'unverified':[],'notes':[]}
PAPER_COLUMNS=['論文ID','発表年','著者','所属機関','国・地域','論文タイトル（原題）','論文タイトル（日本語訳）','掲載誌・国際会議','論文種別','DOI','原文URL','研究目的','研究概要','対象工具','対象加工法','被削材','判定対象の摩耗種類・指標','入力データ','データ規模','データセット名','技術カテゴリ','具体的なモデル・手法','モデルアーキテクチャ','提案手法の技術的新規性','学習方式','転移学習・事前学習の使用','学習に必要なデータ量','既存手法との違い','比較対象となるベースライン','評価指標','判定精度・性能','評価データの規模・クラス数','学習・検証・テストの分割方法','未知の工具・加工条件での評価有無','推論時間・計算環境','主な研究成果','技術的な限界','データ・コード公開有無','論文URL','DOIリンク','参照ページ・表・図番号','エビデンスID','確認状況','未確認事項','Claim ID','主カテゴリ','採用区分','発行年注記']
PRODUCT_COLUMNS=['製品ID','国・地域','企業名','製品・ソリューション名','開発開始年','発表年','販売開始年','現在の提供状況','ツール・ソリューション概要','主な用途','対象工具','対象加工法','判定対象となる摩耗種類','判定可能な状態・指標','使用データ','センサ・撮像方式','加工中／加工後などの使用タイミング','判定技術の基本原理','技術カテゴリ','具体的なAIモデル・アルゴリズム名','モデル構造・処理フロー','学習方式','学習データの必要性','技術的な特徴・独自性','関連特許・共同研究','技術情報の公開状況','判定精度・性能','評価指標と評価条件','処理時間・リアルタイム性','導入に必要な設備・環境','技術的制約','導入実績・販売実績','販売価格・提供形態','想定顧客・用途','対象市場','市場規模','市場規模の対象範囲・算出年・算出方法・出典','市場における特徴・競争優位性','公式製品URL','技術資料URL','関連論文・特許URL','エビデンスID','技術情報の確度','未確認事項','確認済み実装モデル','関連研究モデル','製品関連性根拠','提供区分','Claim ID']
(ROOT/'data').mkdir(exist_ok=True)
(ROOT/'data/schema.json').write_text(json.dumps({'products':PRODUCT_COLUMNS,'papers':PAPER_COLUMNS},ensure_ascii=False,indent=2),encoding='utf-8')

def record(n, meta, url, jp, category, status, raw, locator, **fields):
    p={k:'未確認' for k in PAPER_COLUMNS}
    p.update({'論文ID':f'R{100+n:04d}','論文タイトル（日本語訳）':jp,'主カテゴリ':category,'技術カテゴリ':category,'確認状況':status,'原文URL':url,'論文URL':url,'採用区分':'直接研究','論文種別':'原著論文','発行年注記':'非該当','エビデンスID':f'SIM{n:03d}','参照ページ・表・図番号':locator})
    meta_source=None
    if meta:
        filename,index=meta if isinstance(meta,tuple) else (f'crossref_{meta:02d}.json',None)
        m=json.loads((RAW/filename).read_text(encoding='utf-8'))['message']
        if index is not None: m=m['items'][index]
        authors='; '.join(' '.join([a.get('given',''),a.get('family','')]).strip() for a in m.get('author',[]))
        affiliations=sorted(set(x['name'] for a in m.get('author',[]) for x in a.get('affiliation',[]) if x.get('name')))
        year=(m.get('published-online') or m.get('published') or m.get('published-print'))['date-parts'][0][0]
        p.update({'論文タイトル（原題）':m['title'][0],'著者':authors,'発表年':year,'DOI':m['DOI'].lower(),'DOIリンク':'https://doi.org/'+m['DOI'],'掲載誌・国際会議':'; '.join(m.get('container-title',[])) or '未確認'})
        if affiliations: p['所属機関']='; '.join(affiliations)
        meta_source=f'SIM{n:03d}M'
        B['sources'].append({'source_id':meta_source,'title':'Crossref metadata: '+m['title'][0],'publisher':'Crossref / DOI登録出版社','year':year,'url':'https://api.crossref.org/works/'+m['DOI'],'type':'DOI書誌台帳','primary':'一次情報（登録メタデータ）','accessed':'2026-10-20','verification':'題名・全著者・年・DOI照合','saved_path':'evidence/raw/image/'+filename,'locator':'message（題名検索では選択候補を照合）'})
    p.update(fields)
    p['研究目的']=p['研究目的'] if p['研究目的']!='未確認' else jp
    p['主な研究成果']=p['主な研究成果'] if p['主な研究成果']!='未確認' else p.get('判定精度・性能','未確認')
    p['学習に必要なデータ量']=p['学習に必要なデータ量'] if p['学習に必要なデータ量']!='未確認' else p.get('データ規模','未確認')+'（本研究で使用。必要最小量を意味しない）'
    p['未確認事項']=p['未確認事項'] if p['未確認事項']!='未確認' else ('本文未取得項目、分割、推論条件、未知工場での性能' if '抄録' in status else '未知工場・異工具形状への一般化、商用搭載との関係')
    B['sources'].append({'source_id':f'SIM{n:03d}','title':p['論文タイトル（原題）'],'publisher':p['著者'],'year':p['発表年'],'url':url,'type':p['論文種別'],'primary':'一次情報','accessed':'2026-10-20','verification':status,'saved_path':('evidence/raw/image/'+raw) if raw else '未保存（URL参照）','locator':locator})
    claim_ids=[]
    for field in ['書誌','対象工具','対象加工法','判定対象の摩耗種類・指標','具体的なモデル・手法','モデルアーキテクチャ','学習方式','転移学習・事前学習の使用','データ規模','判定精度・性能','学習・検証・テストの分割方法','未知の工具・加工条件での評価有無','推論時間・計算環境','技術的な限界']:
        value=' / '.join(str(p[x]) for x in ['論文タイトル（原題）','著者','発表年','DOI']) if field=='書誌' else p[field]
        if value=='未確認':continue
        cid=f'CIM{n:03d}_{len(claim_ids)+1:02d}'
        claim_ids.append(cid)
        B['claims'].append({'claim_id':cid,'entity_id':p['論文ID'],'field':field,'claim':value,'status':'確認済み' if '抄録' not in status else '抄録のみ確認'})
        B['claim_evidence'].append({'claim_id':cid,'source_id':meta_source if field=='書誌' and meta_source else f'SIM{n:03d}','locator':'DOI登録書誌' if field=='書誌' and meta_source else locator,'quote':'','verification':'原資料の当該記述を要約。限界のうち一般化不足は調査者評価。'})
    p['Claim ID']='; '.join(claim_ids)
    if meta_source:p['エビデンスID']+='; '+meta_source
    B['papers'].append(p)
    B['unverified'].append({'entity_id':p['論文ID'],'field':'未確認事項','item':p['未確認事項'],'status':'未確認','next_action':'原論文/補足資料・著者公開データで確認'})

